            ("code", "class Learner:\n    def __init__(self, name):\n        self.name = name\n    def introduce(self):\n        return f'I am {self.name}'\nclass LabLearner(Learner):\n    def introduce(self):\n        return f'{super().introduce()} and I study Python'\nlearner = LabLearner('Asha')\nprint(learner.name, learner.introduce())"),
